True def transform(grid):
    rows, cols = len(grid), len(grid[0])
    # A uniform separator divides the two same-sized masks.
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and row[0] not in (0,):
            a, b = grid[:r], grid[r+1:]
            if a and len(a) == len(b):
                return [[2 if x and y else 0 for x, y in zip(ar, br)] for ar, br in zip(a, b)]
    for c in range(cols):
        col = [grid[r][c] for r in range(rows)]
        if len(set(col)) == 1 and col[0] not in (0,):
            a = [row[:c] for row in grid]
            b = [row[c+1:] for row in grid]
            if a and all(len(x) == len(y) for x, y in zip(a, b)):
                return [[2 if x and y else 0 for x, y in zip(ar, br)] for ar, br in zip(a, b)]
    raise ValueError("No matching separator found")
